.c-header { flex: 0 1 auto; height: auto; padding-bottom: 10px; }
.c-header .c-header--top { padding: 10px; height: 60px; margin: 0px; display: flex; place-content: center; align-items: center; }
.c-header .c-header--top { justify-content: space-between; }
.c-header .c-header-back-link { color: rgb(0, 0, 0); font-weight: 600; position: relative; z-index: 5; text-decoration: none; display: flex; justify-content: center; align-items: center; }
.c-header .c-header-back-link i { vertical-align: middle; }
@media (max-width: 767px) {
  .c-header .c-header-back-link span { display: none; }
}
.c-header .c-header-back-link:hover { text-decoration: none; }
body.updated-design .c-help-link a { text-decoration: none; }
body.updated-design .c-help-link span:first-child { text-decoration: underline; }
footer.c-footer .c-footer__menu .c-footer__menu-item-link:focus { box-shadow: rgba(0, 123, 255, 0.5) 0px 0px 0px 0.2rem; box-decoration-break: clone; -webkit-box-decoration-break: clone; }
#main-content:has(.c-institution-selection) { display: flex; justify-content: center; align-items: center; }
.c-institution-selection * { font-family: "Open Sans", sans-serif; }
.c-institution-selection { display: flex; flex-direction: column; align-items: center; padding: 24px; gap: 40px; width: 665px; margin: 56px auto 128px; background: var(--white); border: 1px solid var(--neutral-100); border-radius: 8px; }
.c-institution-selection__header { display: flex; flex-direction: column; gap: 1rem; }
.c-institution-selection__title, .c-institution-selection__subtitle, .c-institution-selection__description { font-size: 16px; line-height: 1.5rem; text-align: left; }
.c-institution-selection__title { font-size: 1.75rem; line-height: 2.25rem; margin: 0px; }
.c-institution-selection__description { font-weight: 400; }
.c-institution-selection__body, .c-institution-selection .c-form { width: 100%; }
.c-institution-selection__current-section, .c-institution-selection__switch-section { width: 100%; margin-bottom: 1rem; }
.c-institution-selection__actions { display: flex; justify-content: flex-end; padding-top: 16px; border-top: 1px solid var(--neutral-100); }
.c-institution-selection__actions .u-button--primary { padding: 0.75rem 1rem; background-color: var(--blue-500); border-width: medium; border-style: none; border-color: currentcolor; border-image: initial; border-radius: 0.25rem; width: 100%; text-align: center; }
.c-institution-selection__actions .u-button--primary:hover { background-color: var(--black); color: var(--white); }
.c-institution-selection.switch-institution { gap: 0.5rem; margin: 1.5rem 1rem; }
.c-institution-selection.switch-institution .c-institution-selection__subtitle { font-weight: 400; margin-bottom: 1rem; }
.c-institution-selection.switch-institution .c-institution-selection__header { width: 100%; }
.c-institution-selection.switch-institution .c-institution-selection__current-section .c-institution-card.c-institution-card--disabled { color: var(--black); background-color: var(--blue-100); border-width: medium; border-style: none; border-color: currentcolor; border-image: initial; }
.c-institution-selection.switch-institution .c-institution-selection__current-section .c-institution-card.c-institution-card--disabled .c-institution-card__content { margin-top: 0.25rem; }
.c-institution-selection.switch-institution .c-institution-selection__current-section .c-institution-card.c-institution-card--disabled .c-institution-card__address-icon i { opacity: 1; }
.c-institution-selection.switch-institution .c-dropdown .c-dropdown__label { display: none; }
.c-institution-list { display: flex; flex-direction: column; gap: 1rem; }
.c-institution-list.c-institution-list__scrollable { position: relative; max-height: 38vh; overflow-y: auto; padding: 3px; }
.c-institution-card { display: grid; grid-template: "logo name role" "address address address" / 56px 1fr; padding: 1rem; column-gap: 8px; width: 100%; background: rgba(0, 0, 0, 0); border: 1px solid var(--neutral-100); border-radius: 8px; transition: box-shadow 0.2s, background 0.2s; text-align: left; }
.c-institution-card:hover { background: var(--blue-950); }
.c-institution-card:hover * { color: var(--white); }
.c-institution-card:hover .c-institution-card__address-icon .icon-svg { filter: brightness(0) invert(1); }
.c-institution-card:focus { outline: rgba(0, 0, 0, 0) solid 3px; outline-offset: 1px; box-shadow: rgba(0, 123, 255, 0.5) 0px 0px 0px 0.2rem; }
.c-institution-card__logo { display: flex; flex-direction: row; justify-content: center; width: 56px; height: 56px; border-radius: 8px; }
.c-institution-card__content { display: flex; flex-direction: column; width: 100%; gap: 0.5rem; }
.c-institution-card__main { display: flex; align-items: center; }
.c-institution-card__name { font-size: 16px; color: var(--black); overflow: hidden; transition: color 0.2s; grid-area: name; }
.c-institution-card__address { display: flex; align-items: center; grid-area: address; }
.c-institution-card__address--details { display: flex; gap: 4px; }
.c-institution-card__address-icon { width: 16px; height: 16px; }
.c-institution-card__address-icon .icon-svg { transition: filter 0.2s; }
.c-institution-card__address-text { font-size: 14px; line-height: 20px; color: var(--neutral-500); transition: color 0.2s; }
.c-institution-card .c-dropdown__list-item-link-chip .c-chip.c-chip--default { display: block; height: fit-content; border-radius: var(--chip-border-radius); max-width: fit-content; color: var(--chip-text-color); font-size: 0.875rem; font-weight: var(--chip-text-weight); padding-top: var(--chip-padding-y); padding-bottom: var(--chip-padding-y); padding-left: var(--chip-padding-x); padding-right: var(--chip-padding-x); background-color: var(--chip-bg-color); border: solid 1px var(--chip-text-color); line-height: 1.25; }
.c-institution-card .c-dropdown__list-item-link-chip .c-chip.c-chip--default { background-color: var(--neutral-50); padding: 6px 8px; }
.c-institution-card__role { transition: color 0.2s; margin-left: auto; grid-area: role; white-space: nowrap; }
.c-institution-card__role .c-chip__text { color: var(--black); }
.c-institution-card[disabled] * { color: inherit; }
.c-institution-card[disabled]:hover { background: rgba(0, 0, 0, 0); }
.c-institution-card[disabled] .icon-svg { opacity: 0.5; }
.c-institution-card[disabled] { pointer-events: none; opacity: 1; background-color: rgb(235, 246, 255); }
.c-institution-card--disabled { border: 2px solid var(--blue-500); }
.c-institution-logo__image { width: 100%; border-radius: 4px; }
.c-institution-logo__placeholder { display: flex; justify-content: center; align-items: center; width: 56px; height: 56px; background: rgb(244, 245, 247); border: 1px solid var(--neutral-100); border-radius: 8px; }
.c-institution-logo__icon { display: flex; align-items: center; }
@media (max-width: 768px) {
  body { background-color: unset; }
  .c-institution-selection { margin: 1rem; padding: 0px; max-width: none; border-width: medium; border-style: none; border-color: currentcolor; border-image: initial; width: auto; }
  .c-institution-selection__header { gap: 0.5rem; padding: 0px 0.5rem; }
  .c-institution-selection__header * { text-align: center; }
  .c-institution-selection__title { font-size: 1.25rem; line-height: 1.75rem; }
  .c-institution-list { gap: 0.5rem; }
  .c-institution-card { display: grid; grid-template: "logo name" "address address" "role role" / 48px 1fr; gap: 8px; align-items: center; }
  .c-institution-card .c-institution-card__logo { grid-area: logo; width: 48px; height: 48px; border-radius: 8px; display: flex; justify-content: center; align-items: center; }
  .c-institution-card .c-institution-card__logo .icon-svg { width: 48px !important; height: 48px !important; }
  .c-institution-card .c-institution-logo__placeholder { width: 48px; height: 48px; }
  .c-institution-card__name { width: auto; }
  .c-institution-card__address { display: flex; align-items: center; gap: 4px; margin-top: 4px; }
  .c-institution-card__role { margin-left: unset; }
  .c-institution-card__main, .c-institution-card__content { display: contents; }
}
.c-language-toggle { position: relative; z-index: 6; }
.c-language-toggle .c-dropdown__button, .c-language-toggle a { transition: box-shadow 0.2s; background-color: rgba(0, 0, 0, 0); }
.c-language-toggle #language-menu { display: block; }
.c-language-toggle #language-menu li a, .c-language-toggle #language-menu .u-button-label { text-align: left; justify-content: left; border-radius: 0px; padding: 10px; height: auto; }
.c-language-toggle label i, .c-language-toggle label span { vertical-align: middle; }
.c-language-toggle a.u-button { font-size: 1.25rem; font-weight: 400; line-height: 1.5; text-transform: uppercase; border-radius: 0px; }
.c-language-toggle ul { width: 180px; border: 1px solid rgb(139, 139, 139); border-radius: 8px; background-color: rgb(255, 255, 255); box-shadow: rgba(0, 0, 0, 0.15) 0px 3px 8px 0px; padding: 10px 0px; list-style: none; position: absolute; right: 0px; top: 30px; display: none; }
.c-language-toggle ul[aria-expanded="true"] { display: block; }
.c-language-toggle ul li a { display: block; padding: 6px 15px; color: rgb(0, 0, 0); position: relative; z-index: 99; }
.c-language-toggle ul li a:visited { color: rgb(0, 0, 0); }
.c-language-toggle ul li a:hover { text-decoration: none; background: rgb(246, 246, 246); color: rgb(27, 96, 244); }
@media (max-width: 1023px) {
  .c-language-toggle ul li { display: block; }
  .c-language-toggle ul li .icon-svg { margin: 0px; }
