  100% { visibility: hidden; transform: translate3d(0px, -100%, 0px); opacity: 0; }
}
@keyframes slideInOut { 
  0% { transform-origin: right center; transform: translateX(3000%); opacity: 0; visibility: visible; }
  14.28% { transform: translateX(0px) scale(1); opacity: 1; }
  85.72% { transform: translateX(0px) scale(1); opacity: 1; }
  100% { transform-origin: right center; transform: translateX(200%); opacity: 0; visibility: hidden; }
}
@keyframes slideInOutTop { 
