:root { --footer-border-color: var(--neutral-100); --footer-bg-color: var(--white); --footer-link-color: var(--default-link-color); --footer-link-hover-color: var(--default-link-hover-color); }
.c-footer { background-color: var(--footer-bg-color); border-top: solid 1px var(--footer-border-color); font-family: "Open Sans", sans-serif; }
.c-footer__container { display: flex; flex-direction: column; align-items: center; gap: 2.5rem; padding-top: 2.5rem; padding-bottom: 1.5rem; padding-inline: 1rem; }
.c-footer__logo { display: block; }
.c-footer__menu { list-style-type: none; padding: 0px; display: flex; flex-direction: column; gap: 0.75rem; }
.c-footer__menu-item { margin: 0px; text-align: center; }
.c-footer__menu-item-link { font-family: "Open Sans", sans-serif; font-weight: 600; text-decoration: underline; color: var(--footer-link-color); }
.c-footer__menu-item-link:hover { color: var(--footer-link-hover-color); }
.c-footer__company-info { font-family: "Open Sans", sans-serif; font-weight: 400; font-size: 0.875rem; line-height: 1.25rem; }
@media only screen and (min-width: 1024px) {
  .c-footer__company-info { font-size: 1rem; line-height: 1.5rem; }
}
.c-footer__company-info { display: flex; flex-wrap: wrap; justify-content: center; gap: 0.25rem 1rem; width: 100%; }
@media only screen and (min-width: 768px) {
  .c-footer__container { align-items: flex-start; }
  .c-footer__company-info { justify-content: flex-start; }
  .c-footer__menu { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 1rem; width: 100%; }
  .c-footer__menu-item { text-align: unset; }
}
@media only screen and (min-width: 1024px) {
  .c-footer__container { padding-inline: 1.5rem; padding-top: 1.5rem; display: grid; grid-template-columns: 25% auto; gap: 1.5rem 1rem; }
  .c-footer__company-info { grid-column: 1 / -1; display: flex; }
}
@media only screen and (min-width: 1920px) {
  .c-footer__container { grid-template-columns: 20% auto; }
  .c-footer__menu { grid-template-columns: 1fr 1fr 1fr 1fr; }
}
