body.updated-design #main-content > .c-card { max-width: 460px; box-shadow: rgba(0, 0, 0, 0.25) 0px 2px 4px 0px; }
@media only screen and (max-width: 767px) {
  body.updated-design #main-content > .c-card { box-shadow: none; border-width: medium; border-style: none; border-color: currentcolor; border-image: initial; }
}
body.updated-design #main-content > .c-card a { font-weight: 600; text-decoration: underline; }
.c-card { margin: 20px auto; max-width: 390px; border: 1px solid var(--neutral-100); border-radius: 8px; padding: 1rem 1.5rem; background-color: var(--white); }
.c-card h1 { font-size: 1.25rem; font-weight: 600; line-height: 1.5; text-align: center; }
.c-card .c-card__h2 { font-size: 1rem; font-weight: 400; line-height: 1.5; text-align: center; }
.c-card a { font-weight: 700; }
@media (max-height: 600px) {
  .c-card { margin-bottom: 50px; }
}
@media (max-width: 480px) {
  .c-card { max-width: 300px; }
}
@media (min-width: 1920px) {
  .c-card { padding-right: 16px; padding-left: 16px; }
}
::-webkit-credentials-auto-fill-button { visibility: hidden; pointer-events: none; position: absolute; right: 0px; }
html, body { height: 100%; text-size-adjust: 100%; }
#skip-link { padding: 6px; left: 0px; width: 200px; height: 40px; color: rgb(255, 255, 255); border-right: 1px solid rgb(255, 255, 255); border-bottom: 1px solid rgb(255, 255, 255); border-bottom-right-radius: 8px; background: rgb(218, 27, 44); transition: top 1s ease-out; }
#skip-link:active, #skip-link:focus { transition: top 0.1s ease-in; }
main { flex: 1 1 auto; }
.c-description-list .c-description-list__term { font-weight: 600; display: block; }
.c-description-list .c-description-list__detail { margin-bottom: 15px; }
body.updated-design .c-form label a, body.updated-design .c-form fieldset a { font-weight: normal; text-decoration: underline; }
body.updated-design .c-form .c-form-field-tip { margin-top: 0.5rem; }
