body.updated-design .c-form .c-form-group input[type="checkbox"]:checked + label::before { background-image: var(--foundations--form-checkbox-checked-image); background-size: 80%; left: 2px; }
body.updated-design .c-form .c-form-group input[type="checkbox"] + label:hover::before { mask: var(--foundations--form-checkbox-checked-image) no-repeat center/1rem; background-color: rgb(255, 255, 255); background-image: none; }
body.updated-design .c-form .c-form-group input[type="checkbox"] + label:hover::after { background-color: rgb(0, 0, 0); border-color: rgb(0, 0, 0); }
body.updated-design .c-form .c-form-field--error .c-form-field__input { border: 1px solid var(--foundations--form-field-error-color); }
body.updated-design .c-form .u-form-control { border: 1px solid var(--neutral-500); border-radius: var(--foundations--form-input-border-radius); }
body:not(.updated-design) .c-form fieldset, body:not(.updated-design) .c-form label { font-weight: 600; }
body:not(.updated-design) .c-form .u-form-control { box-shadow: rgba(0, 0, 0, 0.1) 0px 2px 2px 0px; }
.c-form label, .c-form fieldset { margin-bottom: 8px; display: block; position: relative; }
.c-form label a, .c-form fieldset a { color: rgb(27, 96, 244); font-weight: 700; }
.c-form label a:hover, .c-form fieldset a:hover { text-decoration: none; }
.c-form legend { margin-bottom: 8px; }
.c-form .u-form-control { height: 48px; width: 100%; border: 1px solid var(--neutral-100); border-radius: 4px; background-color: rgb(255, 255, 255); padding: 0.5rem 0.75rem; font-family: "Open Sans", sans-serif; line-height: 1.5; font-size: 16px; }
.c-form .u-form-control:focus { box-shadow: rgb(27, 96, 244) 0px 0px 0px 2px; outline: none; border-color: rgb(27, 96, 244); }
.c-form .u-form-control.u-form-control__error { border: 2px solid rgb(235, 1, 4); }
.c-form .c-form-group { position: relative; margin-bottom: 20px; }
.c-form .c-form-group.c-form-group--error .u-form-control { border: 2px solid rgb(235, 1, 4); }
.c-form .c-form-group.c-form-group--error + label::after { border-color: rgb(235, 1, 4); }
.c-form .c-form-group .c-form-input__prefix { margin-right: 5px; }
.c-form .c-form-group .c-form-group__pass-view { align-items: center; justify-content: flex-end; display: flex; }
.c-form .c-form-group .c-form-group__pass-view:has(> .c-form-group__icon) > input { padding-right: 38px; }
