    width: 50% !important;
    max-width: 50% !important;
    object-fit: contain;
    font-family:'Open Sans', Arial, sans-serif;
}

.slds-button, lightning-button::part(button){
    font-size: larger;
}
.slds-card__header slds-grid {
    background-color: #f9f9f9 !important;
}

.slds-card{
    background-color: #f9f9f9 !important;
}


.slds-button.slds-accordion__summary-action {
    /* color: var(--sds-c-accordion-heading-text-color, var(--dxp-g-root-contrast)); */
    background-color: #f9f9f9;
    color: #696868;
}

/* Hover effect: background color change and zoom-in */
.slds-button.slds-accordion__summary-action:hover {
    background-color: #ececec; /* Light gray background on hover */
    transform: scale(1.01); /* Slightly zoom in */
    cursor: pointer; /* Change cursor to pointer */
    color:  #da1f2d;
}

.slds-nav-vertical__action{
    padding: .5rem 1.5rem .5rem .5rem;
}

.slds-nav-vertical__action:hover   {
    font-weight: bold;
    -webkit-box-shadow: inset 0px 0 0 0;
    box-shadow: inset 0px 0 0 0 ;
}

.slds-form-element__label {
    max-width: fit-content !important;
}

/* Small devices (phones, 600px and down) */
@media (max-width: 600px) {
    .slds-rich-text-editor__output img {
        max-height: 150px !important; /* Adjust as needed for smaller screens */
        max-width: 40% !important;
    }
    .slds-accordion__summary-content{
        font-size: small;
    }

}

/* Medium devices (tablets, 600px to 768px) */
@media (min-width: 601px) and (max-width: 768px) {
    .slds-rich-text-editor__output img {
        max-height: 200px !important; /* Adjust as needed for medium screens */
    }
    
}

/* Large devices (desktops, 768px and up) */
@media (min-width: 769px) {
    .slds-rich-text-editor__output img {
        max-height: 250px !important; /* Adjust as needed for larger screens */
    }
    .slds-accordion__summary-content{
        font-size: large;
    }
    
}

